.mark {
  display: inline-block;
  flex-shrink: 0;
  background: url('data:image/png;base64,') center / contain no-repeat;
}

.sidebarMark {
  display: block;
  flex-shrink: 0;
  background: currentColor;
  mask: url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAzNiAyMCI+PHRleHQgeD0iMCIgeT0iMTQiIGZvbnQtZmFtaWx5PSJBcmlhbCwgc2Fucy1zZXJpZiIgZm9udC1zaXplPSIxNCIgZm9udC13ZWlnaHQ9IjcwMCIgbGV0dGVyLXNwYWNpbmc9Ii0uMzUiPlJhYmI8L3RleHQ+PC9zdmc+') center / contain no-repeat;
}

.name {
  display: inline-block;
  width: 34px;
  height: 20px;
  color: color-mix(in srgb, var(--dsh-sidebar-artwork-foreground) 70%, transparent);
  background: currentColor;
  mask: url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAzNCAyMCI+PHRleHQgeD0iMCIgeT0iMTQiIGZvbnQtZmFtaWx5PSJBcmlhbCwgc2Fucy1zZXJpZiIgZm9udC1zaXplPSIxNCIgZm9udC13ZWlnaHQ9IjUwMCIgbGV0dGVyLXNwYWNpbmc9Ii0uMzUiPkNvZGU8L3RleHQ+PC9zdmc+') center / contain no-repeat;
}

.backdrop {
  position: absolute;
  inset-inline: 0;
  top: 0;
  height: 80px;
  z-index: -1;
  pointer-events: none;
  user-select: none;
  overflow: hidden;
  background: url('data:image/svg+xml;base64,') center bottom / cover no-repeat;
  mask-image: linear-gradient(to bottom, black 0%, black 55%, transparent 92%);
  -webkit-mask-image: linear-gradient(to bottom, black 0%, black 55%, transparent 92%);
}

/* T3 Code's original header overlay, with the local sidebar fill as its fade color. */
.backdrop::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    transparent 28%,
    color-mix(in srgb, var(--dsw-specific-sidebar-fill) 10%, transparent) 40%,
    color-mix(in srgb, var(--dsw-specific-sidebar-fill) 30%, transparent) 52%,
    color-mix(in srgb, var(--dsw-specific-sidebar-fill) 58%, transparent) 64%,
    color-mix(in srgb, var(--dsw-specific-sidebar-fill) 82%, transparent) 75%,
    color-mix(in srgb, var(--dsw-specific-sidebar-fill) 96%, transparent) 85%,
    var(--dsw-specific-sidebar-fill) 93%
  );
}
